using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using LighFight.Runtime;
// Review-only rest-space transfer. No Human Animator evaluation or production changes.
public static class UniqueDanceGenericRetargetReview {
 const string Root="Assets/UniqueDancesReview";
 static readonly string[] Names={"Hips","Spine02","Spine01","Spine","neck","Head","LeftShoulder","LeftArm","LeftForeArm","LeftHand","RightShoulder","RightArm","RightForeArm","RightHand","LeftUpLeg","LeftLeg","LeftFoot","LeftToeBase","RightUpLeg","RightLeg","RightFoot","RightToeBase"};
 static readonly HumanBodyBones[] Human={HumanBodyBones.Hips,HumanBodyBones.Spine,HumanBodyBones.Chest,HumanBodyBones.UpperChest,HumanBodyBones.Neck,HumanBodyBones.Head,HumanBodyBones.LeftShoulder,HumanBodyBones.LeftUpperArm,HumanBodyBones.LeftLowerArm,HumanBodyBones.LeftHand,HumanBodyBones.RightShoulder,HumanBodyBones.RightUpperArm,HumanBodyBones.RightLowerArm,HumanBodyBones.RightHand,HumanBodyBones.LeftUpperLeg,HumanBodyBones.LeftLowerLeg,HumanBodyBones.LeftFoot,HumanBodyBones.LeftToes,HumanBodyBones.RightUpperLeg,HumanBodyBones.RightLowerLeg,HumanBodyBones.RightFoot,HumanBodyBones.RightToes};
 public static void Run(){
  string folder=Root+"/Fighter-9",src=Root+"/GenericSources/action-74.fbx";Directory.CreateDirectory(Path.GetDirectoryName(src));if(!File.Exists(src))File.Copy("../art/source/unique-dances-20261018/action-74.fbx",src);AssetDatabase.ImportAsset(src,ImportAssetOptions.ForceSynchronousImport);
  var importer=(ModelImporter)AssetImporter.GetAtPath(src);importer.animationType=ModelImporterAnimationType.Generic;importer.animationCompression=ModelImporterAnimationCompression.Off;importer.meshCompression=ModelImporterMeshCompression.Off;importer.optimizeGameObjects=false;importer.SaveAndReimport();
  var clip=AssetDatabase.LoadAllAssetsAtPath(src).OfType<AnimationClip>().Single(c=>!c.name.StartsWith("__preview"));if(clip.humanMotion)throw new Exception("Generic source unexpectedly Human");
  var source=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>(src));var original=AssetDatabase.LoadAssetAtPath<GameContent>("Assets/LighFight/Content/GameContent.asset").fighters[9];var target=(GameObject)PrefabUtility.InstantiatePrefab(original);
  try{
   foreach(var actor in new[]{source,target}){foreach(var b in actor.GetComponentsInChildren<MonoBehaviour>(true))b.enabled=false;var a=actor.GetComponentInChildren<Animator>();if(a)a.enabled=false;}
   var animator=target.GetComponentInChildren<Animator>();var sb=Names.Select(n=>source.GetComponentsInChildren<Transform>(true).Single(t=>t.name==n)).ToArray();var tb=Human.Select(h=>animator.GetBoneTransform(h)).ToArray();if(tb.Any(t=>!t))throw new Exception("Missing native target mapping");
   var sRest=sb.Select(t=>t.rotation).ToArray();var tRest=tb.Select(t=>t.rotation).ToArray();var nodes=animator.GetComponentsInChildren<Transform>(true);var restP=nodes.Select(t=>t.localPosition).ToArray();var restQ=nodes.Select(t=>t.localRotation).ToArray();var restS=nodes.Select(t=>t.localScale).ToArray();
   var sourceHip=sb[0].position;var targetHip=tb[0].position;Quaternion align=Basis(tb[14],tb[18],tb[5],tb[0])*Quaternion.Inverse(Basis(sb[14],sb[18],sb[5],sb[0]));
   float scale=(targetHip.y-(tb[16].position.y+tb[20].position.y)*.5f)/(sourceHip.y-(sb[16].position.y+sb[20].position.y)*.5f);if(scale<=0||!float.IsFinite(scale))throw new Exception("Invalid rest scale");
   Action<float> evaluate=t=>{for(int n=0;n<nodes.Length;n++){nodes[n].localPosition=restP[n];nodes[n].localRotation=restQ[n];nodes[n].localScale=restS[n];}clip.SampleAnimation(source,t);tb[0].position=targetHip+align*(sb[0].position-sourceHip)*scale;for(int b=0;b<tb.Length;b++)tb[b].rotation=align*(sb[b].rotation*Quaternion.Inverse(sRest[b]))*Quaternion.Inverse(align)*tRest[b];};
   var paths=nodes.Select(t=>AnimationUtility.CalculateTransformPath(t,animator.transform)).ToArray();var curves=nodes.Select(n=>Enumerable.Range(0,10).Select(i=>new AnimationCurve()).ToArray()).ToArray();var previous=new Quaternion[nodes.Length];bool first=true;int count=Mathf.CeilToInt(clip.length*120);var times=AnimationUtility.GetCurveBindings(clip).SelectMany(b=>AnimationUtility.GetEditorCurve(clip,b).keys.Select(k=>k.time)).Concat(Enumerable.Range(0,count+1).Select(k=>clip.length*k/count)).Distinct().OrderBy(t=>t).ToArray();
   foreach(float t in times){evaluate(t);for(int n=0;n<nodes.Length;n++){var p=nodes[n].localPosition;var q=nodes[n].localRotation;var s=nodes[n].localScale;if(!first&&Quaternion.Dot(previous[n],q)<0)q=new Quaternion(-q.x,-q.y,-q.z,-q.w);previous[n]=q;var values=new[]{p.x,p.y,p.z,q.x,q.y,q.z,q.w,s.x,s.y,s.z};for(int c=0;c<10;c++)Add(curves[n][c],t,values[c]);}first=false;}
   var data=AssetDatabase.LoadAssetAtPath<NativeSupportPoseData>(folder+"/Dance.generic.pose.asset");if(!data){data=ScriptableObject.CreateInstance<NativeSupportPoseData>();AssetDatabase.CreateAsset(data,folder+"/Dance.generic.pose.asset");}data.sourceName="Meshy74_GenericRestWorldDelta_v1";data.duration=clip.length;data.joints=nodes.Select((n,i)=>new NativeSupportPoseData.Joint{path=paths[i],px=curves[i][0],py=curves[i][1],pz=curves[i][2],qx=curves[i][3],qy=curves[i][4],qz=curves[i][5],qw=curves[i][6],sx=curves[i][7],sy=curves[i][8],sz=curves[i][9]}).ToArray();
   var targets=data.Bind(animator.transform);double maximumAngle=0;float maximumPosition=0;int holdouts=Mathf.CeilToInt(clip.length*317);var rows=new List<string>{"time,maxNativeLocalAngleDeg,maxBoneWorldPositionM"};
   for(int k=0;k<=holdouts;k++){float t=clip.length*k/holdouts;evaluate(t);var qs=nodes.Select(n=>n.localRotation).ToArray();var ps=nodes.Select(n=>n.position).ToArray();data.Apply(targets,t);double a=0;float p=0;for(int n=0;n<nodes.Length;n++){a=Math.Max(a,Angle(qs[n],nodes[n].localRotation));p=Mathf.Max(p,Vector3.Distance(ps[n],nodes[n].position));}maximumAngle=Math.Max(maximumAngle,a);maximumPosition=Mathf.Max(maximumPosition,p);rows.Add(t+","+a+","+p);}
   string output="../art/source/unique-dances-20261018/audit/generic-sailor";Directory.CreateDirectory(output);File.WriteAllLines(output+"/subframe-parity.csv",rows);File.WriteAllText(output+"/summary.txt","sourceGeneric=true; originalAvatarUnchanged=true; hipScale="+scale+"; samples="+times.Length+"; holdouts="+(holdouts+1)+"; maxAngleDeg="+maximumAngle+"; maxPositionM="+maximumPosition);
   if(maximumAngle>.15||maximumPosition>.002f)throw new Exception("Generic native retarget interpolation gate failed angle="+maximumAngle+" pos="+maximumPosition);
   UniqueDanceCurvePack.PackOnly("packing-generic-sailor.csv");
   // Derived candidate only. Original rig/mesh/material/Avatar and all other clips stay.
   var candidate=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>(folder+"/Review.clock.prefab"));try{PrefabUtility.UnpackPrefabInstance(candidate,PrefabUnpackMode.Completely,InteractionMode.AutomatedAction);var overlay=candidate.GetComponent<NativeSupportOverlay>();foreach(var entry in overlay.entries)if(entry.state=="Dance")entry.pose=data;PrefabUtility.SaveAsPrefabAsset(candidate,folder+"/Review.generic.prefab");}finally{foreach(var b in candidate.GetComponents<MonoBehaviour>())if(b is IActorCurveWarmup warm)warm.Dispose();UnityEngine.Object.DestroyImmediate(candidate);}AssetDatabase.SaveAssets();Debug.Log("AGENT_RESULT Sailor Generic worlddelta candidate; no promotion");
  }finally{foreach(var a in new[]{source,target}){foreach(var b in a.GetComponents<MonoBehaviour>())if(b is IActorCurveWarmup warm)warm.Dispose();UnityEngine.Object.DestroyImmediate(a);}}
 }
 static Quaternion Basis(Transform l,Transform r,Transform head,Transform hip){Vector3 up=(head.position-hip.position).normalized,right=(r.position-l.position).normalized;return Quaternion.LookRotation(Vector3.Cross(right,up).normalized,up);}
 static void Add(AnimationCurve curve,float t,float v){int n=curve.AddKey(t,v);AnimationUtility.SetKeyLeftTangentMode(curve,n,AnimationUtility.TangentMode.Linear);AnimationUtility.SetKeyRightTangentMode(curve,n,AnimationUtility.TangentMode.Linear);}
 static double Angle(Quaternion a,Quaternion b){double d=(double)a.x*b.x+(double)a.y*b.y+(double)a.z*b.z+(double)a.w*b.w,aa=(double)a.x*a.x+(double)a.y*a.y+(double)a.z*a.z+(double)a.w*a.w,bb=(double)b.x*b.x+(double)b.y*b.y+(double)b.z*b.z+(double)b.w*b.w;return 2*Math.Acos(Math.Min(1,Math.Abs(d)/Math.Sqrt(aa*bb)))*180/Math.PI;}
}
